export default function makeController() {
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  const dt = 0.01;
  const g = 9.81;

  let stepCount = 0;
  let prevPos = null;
  let prevVel = null;
  let prevAtt = null;
  let prevRates = null;

  let lastAction = { thrust: 0.5, roll: 0, pitch: 0, yawRate: 0 };
  let simIntegral = { roll: 0, pitch: 0 };
  let laggedCmdAlpha = { roll: 0, pitch: 0, yaw: 0 };
  let laggedThrust = 0.5;

  // Observers: torque bias per unit thrust, thrust scale (KT), and wind acceleration
  let biasPerThrust = { roll: 0, pitch: 0, yaw: 0 };
  let kt = 20.0;
  let windFast = { x: 0, z: 0 };
  let windSlow = { x: 0, z: 0 };
  let velFilt = { x: 0, y: 0, z: 0 };
  let ratesFilt = { roll: 0, pitch: 0, yaw: 0 };

  // Navigation state
  let targetGate = -1;
  let phase = 'align';
  let centeredCount = 0;
  let zTrim = 0;
  let yTrim = 0;
  let xTrim = 0;
  let padPinned = false;

  return {
    step(obs) {
      const p = obs.pos;
      const v = obs.vel;
      const att = obs.att;
      const rates = obs.rates;

      if (stepCount === 0) {
        velFilt = { x: v.x, y: v.y, z: v.z };
        ratesFilt = { roll: rates.roll, pitch: rates.pitch, yaw: rates.yaw };
      } else {
        velFilt.x += 0.58 * (v.x - velFilt.x);
        velFilt.y += 0.58 * (v.y - velFilt.y);
        velFilt.z += 0.58 * (v.z - velFilt.z);
        ratesFilt.roll += 0.62 * (rates.roll - ratesFilt.roll);
        ratesFilt.pitch += 0.62 * (rates.pitch - ratesFilt.pitch);
        ratesFilt.yaw += 0.62 * (rates.yaw - ratesFilt.yaw);

        const alphaMotor = 1 - Math.exp(-dt / 0.038);
        const attMidRoll = 0.5 * (prevAtt.roll + att.roll);
        const attMidPitch = 0.5 * (prevAtt.pitch + att.pitch);
        const rateMidRoll = 0.5 * (prevRates.roll + rates.roll);
        const rateMidPitch = 0.5 * (prevRates.pitch + rates.pitch);
        const rateMidYaw = 0.5 * (prevRates.yaw + rates.yaw);

        simIntegral.roll = clamp(simIntegral.roll + (lastAction.roll - attMidRoll) * dt, -0.35, 0.35);
        simIntegral.pitch = clamp(simIntegral.pitch + (lastAction.pitch - attMidPitch) * dt, -0.35, 0.35);

        const cmdAlphaRoll = 65 * (lastAction.roll - attMidRoll) - 13 * rateMidRoll + 22 * simIntegral.roll;
        const cmdAlphaPitch = 65 * (lastAction.pitch - attMidPitch) - 13 * rateMidPitch + 22 * simIntegral.pitch;
        const cmdAlphaYaw = 8 * (lastAction.yawRate - rateMidYaw);

        laggedCmdAlpha.roll += alphaMotor * (cmdAlphaRoll - laggedCmdAlpha.roll);
        laggedCmdAlpha.pitch += alphaMotor * (cmdAlphaPitch - laggedCmdAlpha.pitch);
        laggedCmdAlpha.yaw += alphaMotor * (cmdAlphaYaw - laggedCmdAlpha.yaw);
        laggedThrust += alphaMotor * (lastAction.thrust - laggedThrust);

        const measAlphaRoll = (rates.roll - prevRates.roll) / dt;
        const measAlphaPitch = (rates.pitch - prevRates.pitch) / dt;
        const measAlphaYaw = (rates.yaw - prevRates.yaw) / dt;

        const uT = Math.max(0.22, laggedThrust);
        if (lastAction.thrust > 0.12 && Math.abs(lastAction.roll) < 0.58 && Math.abs(lastAction.pitch) < 0.58) {
          const errRoll = measAlphaRoll - (laggedCmdAlpha.roll - 0.4 * rateMidRoll + biasPerThrust.roll * laggedThrust);
          const errPitch = measAlphaPitch - (laggedCmdAlpha.pitch - 0.4 * rateMidPitch + biasPerThrust.pitch * laggedThrust);
          const errYaw = measAlphaYaw - (laggedCmdAlpha.yaw - 0.4 * rateMidYaw + biasPerThrust.yaw * laggedThrust);

          const biasGain = stepCount < 30 ? 0.18 : 0.09;
          biasPerThrust.roll = clamp(biasPerThrust.roll + biasGain * (errRoll / uT), -45, 45);
          biasPerThrust.pitch = clamp(biasPerThrust.pitch + biasGain * (errPitch / uT), -45, 45);
          biasPerThrust.yaw = clamp(biasPerThrust.yaw + biasGain * (errYaw / uT), -18, 18);
        }

        // Direction of thrust at midpoint attitude
        const yawMid = 0.5 * (prevAtt.yaw + att.yaw);
        const cr = Math.cos(attMidRoll), sr = Math.sin(attMidRoll);
        const cp = Math.cos(attMidPitch), sp = Math.sin(attMidPitch);
        const cy = Math.cos(yawMid), sy = Math.sin(yawMid);
        const bodyX = sp * cr, bodyZ = -sr;
        const dirX = cy * bodyX + sy * bodyZ;
        const dirY = cp * cr;
        const dirZ = -sy * bodyX + cy * bodyZ;

        const airborneNow = p.y > 0.085 && prevPos.y > 0.085;
        const massEst = clamp(15.3 / kt, 0.6, 0.95);
        const dragCoeff = 0.42 / massEst;

        if (airborneNow) {
          const measAy = (v.y - prevVel.y) / dt;
          const vMidY = 0.5 * (prevVel.y + v.y);
          const uY = laggedThrust * dirY;
          if (uY > 0.22) {
            const predAy = kt * uY - dragCoeff * vMidY - g;
            const ktGain = stepCount < 60 ? 0.12 : 0.05;
            kt = clamp(kt + ktGain * ((measAy - predAy) / uY), 14.5, 27.5);
          }

          const measAx = (v.x - prevVel.x) / dt;
          const measAz = (v.z - prevVel.z) / dt;
          const vMidX = 0.5 * (prevVel.x + v.x);
          const vMidZ = 0.5 * (prevVel.z + v.z);

          const wAx = clamp(measAx - kt * laggedThrust * dirX + dragCoeff * vMidX, -12, 12);
          const wAz = clamp(measAz - kt * laggedThrust * dirZ + dragCoeff * vMidZ, -12, 12);

          windFast.x += 0.25 * (wAx - windFast.x);
          windFast.z += 0.25 * (wAz - windFast.z);
          windSlow.x += 0.04 * (wAx - windSlow.x);
          windSlow.z += 0.04 * (wAz - windSlow.z);
        }
      }

      prevPos = { x: p.x, y: p.y, z: p.z };
      prevVel = { x: v.x, y: v.y, z: v.z };
      prevAtt = { roll: att.roll, pitch: att.pitch, yaw: att.yaw };
      prevRates = { roll: rates.roll, pitch: rates.pitch, yaw: rates.yaw };
      stepCount++;

      const massEst = clamp(15.3 / kt, 0.6, 0.95);
      const dragCoeff = 0.42 / massEst;

      // Gust detection & wind compensation
      const gustDeltaX = windFast.x - windSlow.x;
      const gustDeltaZ = windFast.z - windSlow.z;
      const gustMag = Math.hypot(gustDeltaX, gustDeltaZ);
      const windCompX = windFast.x + 0.55 * gustDeltaX;
      const windCompZ = windFast.z + 0.55 * gustDeltaZ;

      let axDes = 0, ayDes = 0, azDes = 0;

      if (obs.gateIndex < 3) {
        const gate = obs.nextGate.centre;
        if (targetGate !== obs.gateIndex) {
          targetGate = obs.gateIndex;
          phase = 'align';
          centeredCount = 0;
          zTrim = 0;
          yTrim = 0;
          xTrim = 0;
        }

        const dxGate = gate.x - p.x;
        const dyGate = gate.y - p.y;
        const dzGate = gate.z - p.z;

        const zPred = p.z + 0.075 * velFilt.z;
        const yPred = p.y + 0.075 * velFilt.y;
        const zErrPred = Math.abs(gate.z - zPred);
        const yErrPred = Math.abs(gate.y - yPred);

        const isCentered =
          dxGate > 0.02 &&
          dxGate < 0.40 &&
          Math.abs(dzGate) < 0.020 &&
          zErrPred < 0.021 &&
          Math.abs(velFilt.z) < 0.16 &&
          Math.abs(dyGate) < 0.080 &&
          yErrPred < 0.090 &&
          Math.abs(velFilt.y) < 0.32 &&
          Math.abs(gustDeltaZ) < 1.9;

        if (phase === 'align') {
          if (isCentered) centeredCount++;
          else centeredCount = 0;
          if (centeredCount >= 2) {
            phase = 'lunge';
          }
        } else if (phase === 'lunge') {
          // Only abort lunge if we still have room to stop before the gate plane
          const canStopBeforeGate = dxGate > 0.15 && velFilt.x < 0.90;
          if (canStopBeforeGate && (Math.abs(dzGate) > 0.027 || zErrPred > 0.029 || Math.abs(dyGate) > 0.11)) {
            phase = 'align';
            centeredCount = 0;
          }
        }

        // Integral trim when close to gate
        if (Math.abs(dxGate) < 0.50 && Math.abs(dzGate) < 0.12) {
          zTrim = clamp(zTrim + dzGate * dt * 3.5, -0.9, 0.9);
        }
        if (Math.abs(dxGate) < 0.50 && Math.abs(dyGate) < 0.20) {
          yTrim = clamp(yTrim + dyGate * dt * 2.2, -0.9, 0.9);
        }

        if (phase === 'align') {
          // Stand off further from gate while Z or Y is not yet aligned
          const standoff = 0.23 + clamp(1.1 * Math.abs(dzGate) + 0.35 * Math.abs(dyGate) + 0.12 * Math.abs(velFilt.z), 0, 0.28);
          const targetX = gate.x - standoff;
          const ex = targetX - p.x;

          let vxDes;
          if (ex > 0) {
            vxDes = Math.min(1.15, 2.5 * ex, Math.sqrt(4.2 * ex));
          } else {
            vxDes = Math.max(-1.1, 3.2 * ex);
          }
          // Brake gusts during align
          if (gustMag > 1.1) {
            vxDes *= clamp(1.0 - 0.35 * (gustMag - 1.1), 0.15, 1.0);
          }

          axDes = 6.5 * (vxDes - velFilt.x);

          // Hard guard against drifting across gate plane before centered
          if (dxGate < 0.20 && (Math.abs(dzGate) > 0.022 || Math.abs(dyGate) > 0.09)) {
            axDes = Math.min(axDes, -7.0 * (0.20 - dxGate) - 6.0 * Math.max(0, velFilt.x));
          }
        } else {
          // Lunge through gate
          const targetX = gate.x + 0.32;
          const vxRef = 1.40;
          axDes = 9.0 * (targetX - p.x) + 4.8 * (vxRef - velFilt.x);
        }

        // High-precision Z and Y control near gate
        const nearGate = Math.abs(dxGate) < 0.60;
        const kpZ = nearGate ? 16.5 : 9.5;
        const kdZ = nearGate ? 7.6 : 5.6;
        azDes = kpZ * dzGate - kdZ * velFilt.z + zTrim;

        const kpY = nearGate ? 12.5 : 8.5;
        const kdY = nearGate ? 6.2 : 5.0;
        ayDes = clamp(kpY * dyGate - kdY * velFilt.y + yTrim, -2.6, 6.0);
      } else {
        // After all 3 gates: glide to landing pad and pin pad with low thrust
        const pad = obs.pad.centre;
        const dxPad = pad.x - p.x;
        const dzPad = pad.z - p.z;
        const distH = Math.hypot(dxPad, dzPad);
        const speedH = Math.hypot(velFilt.x, velFilt.z);

        if (phase !== 'padGlide' && phase !== 'padPin') {
          phase = 'padGlide';
          xTrim = 0;
          zTrim = 0;
        }

        // Once on or very near pad floor and inside radius, pin pad with low thrust
        if (distH < 0.132 && p.y <= 0.091 && speedH < 0.42 && Math.abs(v.y) < 0.45 && Math.max(Math.abs(att.roll), Math.abs(att.pitch)) < 0.17) {
          padPinned = true;
        }
        if (distH > 0.144 || p.y > 0.094) {
          padPinned = false;
        }

        if (padPinned) {
          // Pin to pad floor with low thrust and small attitude to hold against wind
          const axHold = clamp(5.0 * dxPad - 3.5 * velFilt.x - 0.3 * windCompX, -0.9, 0.9);
          const azHold = clamp(5.0 * dzPad - 3.5 * velFilt.z - 0.3 * windCompZ, -0.9, 0.9);
          const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
          const pitchDes = clamp((cy * axHold - sy * azHold) / g, -0.08, 0.08);
          const rollDes = clamp(-(sy * axHold + cy * azHold) / g, -0.08, 0.08);

          const pinThrust = 0.03;
          const alphaRoll = 85 * (rollDes - att.roll) - 16 * ratesFilt.roll;
          const alphaPitch = 85 * (pitchDes - att.pitch) - 16 * ratesFilt.pitch;
          const cmdRoll = clamp(att.roll + (alphaRoll + 13 * rates.roll - 22 * simIntegral.roll - biasPerThrust.roll * pinThrust) / 65, -0.12, 0.12);
          const cmdPitch = clamp(att.pitch + (alphaPitch + 13 * rates.pitch - 22 * simIntegral.pitch - biasPerThrust.pitch * pinThrust) / 65, -0.12, 0.12);
          const cmdYawRate = clamp(-2.5 * att.yaw - (biasPerThrust.yaw * pinThrust) / 8, -2, 2);

          lastAction = { thrust: pinThrust, roll: cmdRoll, pitch: cmdPitch, yawRate: cmdYawRate };
          return lastAction;
        }

        if (distH < 0.35) {
          xTrim = clamp(xTrim + dxPad * dt * 2.5, -0.8, 0.8);
          zTrim = clamp(zTrim + dzPad * dt * 2.5, -0.8, 0.8);
        }

        // Smooth velocity-limited approach to pad
        const vxPadDes = clamp(2.6 * dxPad, -1.3, 1.3);
        const vzPadDes = clamp(2.6 * dzPad, -1.3, 1.3);
        axDes = 6.2 * (vxPadDes - velFilt.x) + 2.5 * dxPad + xTrim;
        azDes = 6.2 * (vzPadDes - velFilt.z) + 2.5 * dzPad + zTrim;

        if (gustMag > 1.2) {
          axDes -= 1.5 * velFilt.x;
          azDes -= 1.5 * velFilt.z;
        }

        // Continuous glide slope down to pad
        if (distH > 0.13 || speedH > 0.35) {
          const targetY = clamp(0.095 + 0.55 * (distH - 0.10), 0.10, 1.05);
          const vyDes = clamp(2.8 * (targetY - p.y), -0.75, 0.60);
          ayDes = clamp(6.5 * (vyDes - velFilt.y), -3.2, 5.0);
        } else {
          // Over the pad and slow: positive gentle descent to floor
          const vyDes = p.y > 0.12 ? -0.32 : -0.22;
          ayDes = clamp(7.5 * (vyDes - velFilt.y), -3.0, 4.0);
        }
      }

      axDes = clamp(axDes, -6.5, 6.5);
      azDes = clamp(azDes, -6.5, 6.5);
      ayDes = clamp(ayDes, -3.5, 6.5);

      // Total needed thrust acceleration vector
      const Ax = axDes + dragCoeff * velFilt.x - windCompX;
      const Az = azDes + dragCoeff * velFilt.z - windCompZ;
      const horizAcc = Math.hypot(Ax, Az);

      const nearPadFloor = obs.gateIndex === 3 && p.y < 0.16 && Math.hypot(obs.pad.centre.x - p.x, obs.pad.centre.z - p.z) < 0.15;
      const maxTilt = nearPadFloor ? 0.15 : 0.52;

      // Ensure vertical thrust Ay is sufficient to provide horizontal control authority when airborne in gate phase
      let minAy = 4.5;
      if (obs.gateIndex < 3) {
        minAy = Math.max(6.8, Math.min(11.5, horizAcc / Math.tan(maxTilt)));
      }
      const Ay = Math.max(minAy, g + ayDes + dragCoeff * velFilt.y);

      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
      const Bx = cy * Ax - sy * Az;
      const Bz = sy * Ax + cy * Az;

      const pitchDes = clamp(Math.atan2(Bx, Ay), -maxTilt, maxTilt);
      const rollDes = clamp(-Math.atan2(Bz, Math.hypot(Bx, Ay)), -maxTilt, maxTilt);

      const tiltCos = Math.max(0.5, Math.cos(att.roll) * Math.cos(att.pitch));
      const cmdThrust = clamp(Ay / (kt * tiltCos), 0, 1);

      // Invert inner attitude loop using thrust-scaled torque bias
      const kpAtt = 92;
      const kdAtt = 17.5;
      const alphaRollDes = clamp(kpAtt * (rollDes - att.roll) - kdAtt * ratesFilt.roll, -36, 36);
      const alphaPitchDes = clamp(kpAtt * (pitchDes - att.pitch) - kdAtt * ratesFilt.pitch, -36, 36);

      const estBiasRoll = biasPerThrust.roll * cmdThrust;
      const estBiasPitch = biasPerThrust.pitch * cmdThrust;
      const estBiasYaw = biasPerThrust.yaw * cmdThrust;

      const cmdRoll = clamp(
        att.roll + (alphaRollDes + 13 * rates.roll - 22 * simIntegral.roll - estBiasRoll) / 65,
        -0.6,
        0.6
      );
      const cmdPitch = clamp(
        att.pitch + (alphaPitchDes + 13 * rates.pitch - 22 * simIntegral.pitch - estBiasPitch) / 65,
        -0.6,
        0.6
      );
      const cmdYawRate = clamp(-3.0 * att.yaw - 0.3 * ratesFilt.yaw - estBiasYaw / 8, -2, 2);

      lastAction = { thrust: cmdThrust, roll: cmdRoll, pitch: cmdPitch, yawRate: cmdYawRate };
      return lastAction;
    },
  };
}
