        velFilt.x += 0.55 * (v.x - velFilt.x);
        velFilt.y += 0.55 * (v.y - velFilt.y);
        velFilt.z += 0.55 * (v.z - velFilt.z);
        ratesFilt.roll += 0.6 * (rates.roll - ratesFilt.roll);
        ratesFilt.pitch += 0.6 * (rates.pitch - ratesFilt.pitch);
        ratesFilt.yaw += 0.6 * (rates.yaw - ratesFilt.yaw);

