      prevRates = { roll: rates.roll, pitch: rates.pitch, yaw: rates.yaw };
      stepCount++;

      const massEst = clamp(15.3 / kt, 0.6, 0.95);
      const dragCoeff = 0.42 / massEst;

      // Gust detection & wind compensation
      const gustDeltaX = windFast.x - windSlow.x;
      const gustDeltaZ = windFast.z - windSlow.z;
      const gustMag = Math.hypot(gustDeltaX, gustDeltaZ);
      const windCompX = windFast.x + 0.55 * gustDeltaX;
      const windCompZ = windFast.z + 0.55 * gustDeltaZ;

      let axDes = 0, ayDes = 0, azDes = 0;

      if (obs.gateIndex < 3) {
        const gate = obs.nextGate.centre;
        if (targetGate !== obs.gateIndex) {
          targetGate = obs.gateIndex;
          phase = 'align';
          centeredCount = 0;
          zTrim = 0;
          yTrim = 0;
        }

        const dxGate = gate.x - p.x;
        const dyGate = gate.y - p.y;
        const dzGate = gate.z - p.z;

        const zPred = p.z + 0.07 * velFilt.z;
        const yPred = p.y + 0.07 * velFilt.y;
        const zErrPred = Math.abs(gate.z - zPred);
        const yErrPred = Math.abs(gate.y - yPred);

        const isCentered =
          dxGate > 0.02 &&
          dxGate < 0.42 &&
          Math.abs(dzGate) < 0.018 &&
          zErrPred < 0.020 &&
          Math.abs(velFilt.z) < 0.14 &&
          Math.abs(dyGate) < 0.07 &&
          yErrPred < 0.08 &&
          Math.abs(velFilt.y) < 0.28 &&
          gustMag < 1.6;

        if (phase === 'align') {
          if (isCentered) centeredCount++;
          else centeredCount = Math.max(0, centeredCount - 1);
          if (centeredCount >= 3) {
            phase = 'lunge';
          }
        } else if (phase === 'lunge') {
          // If still safely before gate plane and blown off-center, abort lunge and re-align
          if (dxGate > 0.14 && velFilt.x < 0.95 && (Math.abs(dzGate) > 0.026 || zErrPred > 0.029 || Math.abs(dyGate) > 0.105)) {
            phase = 'align';
            centeredCount = 0;
          }
        }

        // Integral trim when close to gate
        if (Math.abs(dxGate) < 0.45 && Math.abs(dzGate) < 0.12) {
          zTrim = clamp(zTrim + dzGate * dt * 3.0, -0.8, 0.8);
        }
        if (Math.abs(dxGate) < 0.45 && Math.abs(dyGate) < 0.20) {
          yTrim = clamp(yTrim + dyGate * dt * 2.0, -0.8, 0.8);
        }

        let targetX;
        let vxRef = 0;
        if (phase === 'align') {
          // Stay in front of gate; if not yet aligned in z/y, hold further back
          const alignDist = (Math.abs(dzGate) > 0.06 || Math.abs(dyGate) > 0.15) ? 0.34 : 0.24;
          targetX = gate.x - alignDist;
          axDes = 7.5 * (targetX - p.x) - 5.2 * velFilt.x;
          // Brake gusts during align
          if (gustMag > 1.2) {
            axDes -= 1.8 * velFilt.x;
          }
          // Prevent crossing gate plane while uncentered
          if (dxGate < 0.18 && (Math.abs(dzGate) > 0.024 || Math.abs(dyGate) > 0.09)) {
            axDes = Math.min(axDes, -6.0 * (0.18 - dxGate) - 5.5 * Math.max(0, velFilt.x));
          }
        } else {
          // Lunge through gate
          targetX = gate.x + 0.35;
          vxRef = 1.35;
          axDes = 9.0 * (targetX - p.x) + 4.5 * (vxRef - velFilt.x);
        }

        // High-precision Z and Y control near gate
        const nearGate = Math.abs(dxGate) < 0.55;
        const kpZ = nearGate ? 15.0 : 8.5;
        const kdZ = nearGate ? 7.2 : 5.2;
        azDes = kpZ * dzGate - kdZ * velFilt.z + zTrim;

        const kpY = nearGate ? 12.0 : 8.0;
        const kdY = nearGate ? 6.0 : 4.8;
        ayDes = kpY * dyGate - kdY * velFilt.y + yTrim;
      } else {
        // After all 3 gates: fly to landing pad and pin pad with low thrust
        const pad = obs.pad.centre;
        const dxPad = pad.x - p.x;
        const dzPad = pad.z - p.z;
        const distH = Math.hypot(dxPad, dzPad);
        const speedH = Math.hypot(velFilt.x, velFilt.z);

        if (phase !== 'padApproach' && phase !== 'padDescend' && phase !== 'padPin') {
          phase = 'padApproach';
          zTrim = 0;
        }

        // Once close to pad floor and inside radius, pin pad with low thrust
        if (distH < 0.132 && p.y <= 0.092 && speedH < 0.42 && Math.abs(v.y) < 0.45) {
          padPinned = true;
        }
        if (distH > 0.144) {
          padPinned = false;
        }

        if (padPinned) {
          // Pin to pad floor with low thrust and small attitude to hold against wind
          const axHold = clamp(6.0 * dxPad - 4.0 * velFilt.x - windCompX, -1.2, 1.2);
          const azHold = clamp(6.0 * dzPad - 4.0 * velFilt.z - windCompZ, -1.2, 1.2);
          const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
          const pitchDes = clamp((cy * axHold - sy * azHold) / g, -0.10, 0.10);
          const rollDes = clamp(-(sy * axHold + cy * azHold) / g, -0.10, 0.10);

          const alphaRoll = 80 * (rollDes - att.roll) - 16 * ratesFilt.roll;
          const alphaPitch = 80 * (pitchDes - att.pitch) - 16 * ratesFilt.pitch;
          const cmdRoll = clamp(att.roll + (alphaRoll + 13 * rates.roll - 22 * simIntegral.roll - torqueBias.roll) / 65, -0.14, 0.14);
          const cmdPitch = clamp(att.pitch + (alphaPitch + 13 * rates.pitch - 22 * simIntegral.pitch - torqueBias.pitch) / 65, -0.14, 0.14);
          const cmdYawRate = clamp(-2.5 * att.yaw - torqueBias.yaw / 8, -2, 2);

          lastAction = { thrust: 0.04, roll: cmdRoll, pitch: cmdPitch, yawRate: cmdYawRate };
          return lastAction;
        }

        let targetY;
        if (distH > 0.22) {
          targetY = Math.max(0.20, Math.min(0.75, 0.12 + 0.65 * distH));
        } else if (distH > 0.115 || speedH > 0.32) {
          targetY = 0.12;
        } else {
          targetY = -0.02;
        }

        axDes = 8.5 * dxPad - 5.6 * velFilt.x;
        azDes = 8.5 * dzPad - 5.6 * velFilt.z;
        ayDes = 10.5 * (targetY - p.y) - 6.0 * velFilt.y;

        // Soft touchdown speed limit near floor
        if (p.y < 0.22 && velFilt.y < -0.38) {
          ayDes = Math.max(ayDes, -6.5 * (velFilt.y + 0.28));
        }
      }

      axDes = clamp(axDes, -6.5, 6.5);
      azDes = clamp(azDes, -6.5, 6.5);
      ayDes = clamp(ayDes, -4.0, 6.5);

      // Total needed thrust acceleration vector
      const Ax = axDes + dragCoeff * velFilt.x - windCompX;
      const Az = azDes + dragCoeff * velFilt.z - windCompZ;
      const Ay = Math.max(3.0, g + ayDes + dragCoeff * velFilt.y);

      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
      const Bx = cy * Ax - sy * Az;
      const Bz = sy * Ax + cy * Az;

      const maxTilt = (obs.gateIndex === 3 && p.y < 0.20) ? 0.22 : 0.50;
      const pitchDes = clamp(Math.atan2(Bx, Ay), -maxTilt, maxTilt);
      const rollDes = clamp(-Math.atan2(Bz, Math.hypot(Bx, Ay)), -maxTilt, maxTilt);

      // Invert inner attitude loop
      const kpAtt = 90;
      const kdAtt = 17;
      const alphaRollDes = kpAtt * (rollDes - att.roll) - kdAtt * ratesFilt.roll;
      const alphaPitchDes = kpAtt * (pitchDes - att.pitch) - kdAtt * ratesFilt.pitch;

      const cmdRoll = clamp(
        att.roll + (alphaRollDes + 13 * rates.roll - 22 * simIntegral.roll - torqueBias.roll) / 65,
        -0.6,
        0.6
      );
      const cmdPitch = clamp(
        att.pitch + (alphaPitchDes + 13 * rates.pitch - 22 * simIntegral.pitch - torqueBias.pitch) / 65,
        -0.6,
        0.6
      );
      const cmdYawRate = clamp(-3.0 * att.yaw - 0.3 * ratesFilt.yaw - torqueBias.yaw / 8, -2, 2);

      const tiltCos = Math.max(0.5, Math.cos(att.roll) * Math.cos(att.pitch));
      const cmdThrust = clamp(Ay / (kt * tiltCos), 0, 1);

      lastAction = { thrust: cmdThrust, roll: cmdRoll, pitch: cmdPitch, yawRate: cmdYawRate };
      return lastAction;
    },
  };
}
