          const azHold = clamp(6.0 * dzPad - 4.0 * velFilt.z - windCompZ, -1.2, 1.2);
          const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
          const pitchDes = clamp((cy * axHold - sy * azHold) / g, -0.10, 0.10);
          const rollDes = clamp(-(sy * axHold + cy * azHold) / g, -0.10, 0.10);

