          const measAy = (v.y - prevVel.y) / dt;
          const vMidY = 0.5 * (prevVel.y + v.y);
          const uY = laggedThrust * dirY;
          if (uY > 0.22) {
            const predAy = kt * uY - dragCoeff * vMidY - g;
            const ktGain = stepCount < 60 ? 0.12 : 0.05;
