        azDes = 8.5 * dzPad - 5.6 * velFilt.z;
        ayDes = 11.0 * (targetY - p.y) - 6.0 * velFilt.y;

        if (p.y < 0.20 && velFilt.y < -0.42) {
          ayDes = Math.max(ayDes, -6.5 * (velFilt.y + 0.32));
