          const cmdYawRate = clamp(-2.5 * att.yaw - torqueBias.yaw / 8, -2, 2);

          lastAction = { thrust: 0.04, roll: cmdRoll, pitch: cmdPitch, yawRate: cmdYawRate };
          return lastAction;
        }

        let targetY;
        if (distH > 0.24) {
          targetY = Math.max(0.16, Math.min(0.68, 0.08 + 0.58 * distH));
        } else if (distH > 0.140 || speedH > 0.44) {
          targetY = 0.088;
        } else {
          targetY = -0.05;
        }

        axDes = 8.5 * dxPad - 5.6 * velFilt.x;
        azDes = 8.5 * dzPad - 5.6 * velFilt.z;
        ayDes = 11.0 * (targetY - p.y) - 6.0 * velFilt.y;

        if (p.y < 0.20 && velFilt.y < -0.42) {
